import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"雨无正","description":"","frontmatter":{"title":"雨无正","date":"2026-11-08T00:00:00.000Z","seq":34,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/雨无正.md","filePath":"blogs/诗经·小雅/雨无正.md"}'),p={name:"blogs/诗经·小雅/雨无正.md"};function c(l,a,r,n,_,m){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="雨无正" tabindex="-1">雨无正 <a class="header-anchor" href="#雨无正" aria-label="Permalink to &quot;雨无正&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">浩浩昊天，不骏其德。降丧饥馑，斩伐四国。旻天疾威，弗虑弗图。舍彼有罪，既伏其辜。若此无罪，沦胥以铺。</p><p class="poem-stanza">周宗既灭，靡所止戾。正大夫离居，莫知我勚。三事大夫，莫肯夙夜。邦君诸侯，莫肯朝夕。庶曰式臧，覆出为恶。</p><p class="poem-stanza">如何昊天，辟言不信。如彼行迈，则靡所臻。凡百君子，各敬尔身。胡不相畏，不畏于天？</p><p class="poem-stanza">戎成不退，饥成不遂。曾我暬御，惨惨日瘁。凡百君子，莫肯用讯。听言则答，谮言则退。</p><p class="poem-stanza">哀哉不能言，匪舌是出，维躬是瘁。哿矣能言，巧言如流，俾躬处休！</p><p class="poem-stanza">维曰予仕，孔棘且殆。云不何使，得罪于天子；亦云可使，怨及朋友。</p><p class="poem-stanza">谓尔迁于王都。曰予未有室家。鼠思泣血，无言不疾。昔尔出居，谁从作尔室？</p></div>',3)])])}const u=e(p,[["render",c]]);export{d as __pageData,u as default};
